def gcd(a, b):
    while b:
        a, b = b, a % b
    return a

def lcm(a, b):
    if a == 0 or b == 0:
        return 0
    return abs(a * b) // gcd(a, b)

def is_korean(a):
    n = len(a)
    good_partitions = 0
    for k in range(1, n):
        Ak = a[:k]
        Bk = a[k:]
        lcm_Ak = Ak[0]
        for x in Ak[1:]:
            lcm_Ak = lcm(lcm_Ak, x)
        gcd_Bk = Bk[0]
        for x in Bk[1:]:
            gcd_Bk = gcd(gcd_Bk, x)
        if lcm_Ak == gcd_Bk:
            good_partitions += 1
    return good_partitions

# Test some sequences
print(is_korean([1, 2, 3, 6])) # Should be 2 (k=1, k=3)
print(is_korean([1, 2, 3, 12, 18, 36])) # Should be 3 (k=1, k=3, k=5)
print(is_korean([2, 3, 6, 12, 18, 36])) # Should be 3 (k=2, k=3, k=5)

import itertools

def is_valid(S, n):
    if not S: return True
    # No three consecutive
    for i in range(len(S) - 2):
        if S[i+1] == S[i] + 1 and S[i+2] == S[i+1] + 1:
            return False
    # (1, 2) not allowed
    if len(S) >= 2 and S[0] == 1 and S[1] == 2:
        return False
    # (n-2, n-1) not allowed
    if len(S) >= 2 and S[-1] == n - 1 and S[-2] == n - 2:
        return False
    return True

def max_m(n):
    max_m = 0
    for r in range(1, n):
        for S in itertools.combinations(range(1, n), r):
            if is_valid(S, n):
                max_m = max(max_m, r)
    return max_m

