def max_m_fast(n):
    # Use dynamic programming to find the max size of S
    # dp[i][last_count][first_is_1]
    # i: current index (1 to n-1)
    # last_count: number of consecutive elements ending at i
    # first_is_1: whether the first element was 1

    # We can't use DP easily because the (n-2, n-1) condition is at the end.
    # Let's use a simpler DP and check the end condition.

    # dp[i][last_count][first_is_1] = max size
    # last_count: 0, 1, or 2
    # first_is_1: 0 or 1

    dp = {} # (i, last_count, first_is_1) -> max_size

    # Base case: i=1
    dp[(1, 0, 0)] = 0 # 1 is not picked
    dp[(1, 1, 1)] = 1 # 1 is picked

    for i in range(2, n):
        new_dp = {}
        for (prev_i, last_count, first_is_1), size in dp.items():
            # Option 1: don't pick i
            new_dp[(i, 0, first_is_1)] = max(new_dp.get((i, 0, first_is_1), 0), size)

            # Option 2: pick i
            if last_count < 2:
                if not (first_is_1 == 1 and i == 2 and last_count == 1):
                    new_dp[(i, last_count + 1, first_is_1)] = max(new_dp.get((i, last_count + 1, first_is_1), 0), size + 1)
        dp = new_dp

    max_m = 0
    for (i, last_count, first_is_1), size in dp.items():
        # Final condition: (n-2, n-1) not allowed
        # This means if i=n-1 was picked, i=n-2 could not have been picked
        # if last_count == 2, then i and i-1 were picked.
        # If i=n-1, this is (n-2, n-1).
        if not (i == n - 1 and last_count == 2):
            max_m = max(max_m, size)

    return max_m

